<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$s=$db->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['role']=$u['role'];go('index.php');}$err='Invalid login.';}head('Login');?><section class="form"><h1>Login</h1><p><?=h($err)?></p><form method="post"><input type="hidden" name="token" value="<?=h(token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form></section><?php foot();?>